import type { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import { prisma } from "@/src/lib/prisma";
import bcrypt from "bcrypt";

export const authOptions: NextAuthOptions = {
  providers: [
    CredentialsProvider({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "text" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (credentials?.email === "guest@proje.com" && credentials?.password === "guest123") {
          let guestUser = await prisma.user.findUnique({ where: { email: "guest@proje.com" } });
          if (!guestUser) {
            const hashedGuestPassword = await bcrypt.hash("guest123", 10);
            guestUser = await prisma.user.create({
              data: { email: "guest@proje.com", password: hashedGuestPassword, name: "Guest User", role: "USER", gender: "other" },
            });
          }
          return { id: guestUser.id, email: guestUser.email, role: guestUser.role, gender: guestUser.gender, image: guestUser.image };
        }
        if (!credentials?.email || !credentials?.password) return null;
        const user = await prisma.user.findUnique({ where: { email: credentials.email } });
        if (!user || !user.password) return null;
        const isValid = await bcrypt.compare(credentials.password, user.password);
        if (!isValid) return null;
        return { id: user.id, email: user.email, role: user.role, gender: user.gender, image: user.image as string };
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user, trigger, session }) {
      if (user) {
        token.id = user.id;
        token.role = (user as any).role;
        token.gender = (user as any).gender;
        token.picture = (user as any).image;
      }
      if (trigger === "update" && session?.user) {
        token.gender = session.user.gender;
        token.picture = session.user.image;
        token.email = session.user.email;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        (session.user as any).id = token.id;
        (session.user as any).role = token.role;
        (session.user as any).gender = token.gender;
        session.user.image = token.picture as string;
      }
      return session;
    },
  },
  session: { strategy: "jwt" },
  pages: { signIn: "/auth/signin" },
  secret: process.env.NEXTAUTH_SECRET,
};